<?php
namespace App\Http\Controllers\Demo\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\StaffRequest; use App\Models\Staff; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class StaffController extends Controller { private function find(int$id):Staff{return Staff::where('shop_id',auth()->user()->shop_id)->findOrFail($id);} public function index():View{$shop=auth()->user()->shop;return view('demo.admin.staffs.index',['staffs'=>$shop->staffs()->with('services')->orderBy('display_order')->get(),'services'=>$shop->services()->where('is_active',true)->get()]);} public function store(StaffRequest$r):RedirectResponse{$data=$r->safe()->except('service_ids');$staff=auth()->user()->shop->staffs()->create($data+['is_active'=>$r->boolean('is_active'),'can_accept_reservations'=>$r->boolean('can_accept_reservations')]);$staff->services()->sync($r->input('service_ids',[]));return back()->with('success','スタッフを追加しました。');} public function update(StaffRequest$r,int$staff):RedirectResponse{$item=$this->find($staff);$item->update($r->safe()->except('service_ids')+['is_active'=>$r->boolean('is_active'),'can_accept_reservations'=>$r->boolean('can_accept_reservations')]);$item->services()->sync($r->input('service_ids',[]));return back()->with('success','スタッフを更新しました。');} public function destroy(int$staff):RedirectResponse{$this->find($staff)->delete();return back()->with('success','スタッフを非表示にしました。');} }
